    const selected=channels.find(c=>c.id===mappings[key]);const selectedLabel=selected?(categories[selected.parentId]?categories[selected.parentId]+' / ':'')+'#'+selected.name+' ['+(selected.type===5?'announcement':'text')+']':'';
